fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Pre-allocate a result vector of the same length
    let mut weights = Vec::with_capacity(n);

    for i in 0..n {
        // Endpoints (first and last) get weight 0.5, others get 1.0
        if i == 0 || i == n - 1 {
            weights.push(0.5);
        } else {
            weights.push(1.0);
        }
    }

    weights
}

// Example usage and simple test
fn main() {
    let v1 = vec![2.0f32];
    assert_eq!(chebweight(v1), vec![0.5]);

    let v2 = vec![1.0f32, 2.0, 3.0];
    assert_eq!(chebweight(v2), vec![0.5, 1.0, 0.5]);

    let v3 = vec![0.0f32, 1.0, 2.0, 3.0, 4.0];
    assert_eq!(chebweight(v3), vec![0.5, 1.0, 1.0, 1.0, 0.5]);

    println!("All tests passed!");
}